 {tab==='overview'&&<div className="bulk adminOverview"><style>{".adminOverview{padding:24px!important}.adminStats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:20px 0}.adminStat{padding:18px;border:1px solid var(--glass-border,rgba(255,255,255,.14));border-radius:18px;background:rgba(255,255,255,.045);display:flex;flex-direction:column;gap:7px;min-width:0}.adminStat span,.adminStat small{color:var(--muted,#9ca3af);font-size:12px}.adminStat strong{font-size:clamp(18px,3vw,28px);overflow-wrap:anywhere}.adminQuickActions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.adminOverview .muted{margin-top:18px}.adminOverview .adminSectionHead{align-items:center}@media(max-width:620px){.adminStats{grid-template-columns:repeat(2,minmax(0,1fr))}.adminOverview{padding:16px!important}.adminQuickActions button{flex:1 1 42%}}"} </style><div className="adminSectionHead"><div><h2>Workspace overview</h2><p>Your MaseNet publishing controls at a glance.</p></div><span className="adminBadge"><ShieldCheck size={14}/> Admin access</span></div><div className="adminStats"><div className="adminStat"><span>Library titles</span><strong>{titles.length}</strong><small>Movies and dramas</small></div><div className="adminStat"><span>Episodes</span><strong>{titles.reduce((n,t)=>n+t.episodes.length,0)}</strong><small>Across all libraries</small></div><div className="adminStat"><span>Homepage sections</span><strong>{rows.length}</strong><small>Currently enabled</small></div><div className="adminStat"><span>Telegram bot</span><strong>{telegramStatus.connected?'Connected':'Check status'}</strong><small>{telegramStatus.connected?'Ready for bot workflows':'Use Check bot below'}</small></div></div><div className="adminSectionHead" style={{marginTop:24}}><div><h2>Platform analytics</h2><p>Recorded activity since analytics was enabled.</p></div><button className="secondary" onClick={()=>void loadAnalytics()} disabled={analyticsLoading}>{analyticsLoading?'Refreshing…':'Refresh statistics'}</button></div>{analyticsError&&<p className="muted">{analyticsError}</p>}<div className="adminStats"><div className="adminStat"><span>Unique visitors</span><strong>{analytics?.totals?.visitors??'—'}</strong><small>Anonymous browser IDs</small></div><div className="adminStat"><span>Page views</span><strong>{analytics?.totals?.page_views??'—'}</strong><small>Recorded page visits</small></div><div className="adminStat"><span>Title views</span><strong>{analytics?.totals?.title_views??'—'}</strong><small>Recorded detail views</small></div><div className="adminStat"><span>Searches</span><strong>{analytics?.totals?.searches??'—'}</strong><small>Terms submitted to tracking</small></div></div>{analytics?.daily?.length>0&&<div className="adminStat"><b>Recent activity · last 7 days</b>{analytics.daily.map((d:any)=><div key={d.day} style={{display:'flex',justifyContent:'space-between',gap:12,padding:'7px 0'}}><span>{d.day}</span><span>{d.visitors} visitors · {d.events} events</span></div>)}</div>}{analytics?.popular?.length>0&&<div className="adminStat" style={{marginTop:12}}><b>Popular titles</b>{analytics.popular.map((x:any)=><div key={String(x.id)+x.name} style={{display:'flex',justifyContent:'space-between',gap:12,padding:'7px 0'}}><span>{x.name}</span><span>{x.views} views</span></div>)}</div>}{analytics?.searches?.length>0&&<div className="adminStat" style={{marginTop:12}}><b>Top searches</b>{analytics.searches.map((x:any)=><div key={x.query} style={{display:'flex',justifyContent:'space-between',gap:12,padding:'7px 0'}}><span>{x.query}</span><span>{x.count}</span></div>)}</div>}<div className="adminQuickActions"><button className="primary" onClick={()=>setTab('bulkUrl')}><Link2 size={15}/> Bulk URLs</button><button className="secondary" onClick={()=>setTab('bulkAutoUrl')}><Film size={15}/> Auto Bulk URLs</button><button className="secondary" onClick={()=>setTab('homepage')}><LayoutDashboard size={15}/> Homepage layout</button><button className="secondary" onClick={()=>setTab('broadcast')}><Send size={15}/> Broadcast</button></div><p className="muted">Video file uploads remain disabled. Use video URLs for episodes and upload poster artwork from your phone Gallery inside either URL workflow.</p></div>}
